$OdinReviewCheck = @'
import ast, hashlib, json, pathlib, subprocess
root=pathlib.Path.cwd()
results=[]
def check(name, passed, detail=None):
    results.append({'name':name,'status':'PASS' if passed else 'FAIL','detail':detail})
    if not passed: raise AssertionError(name)
a=root/'crates/odin-engine/tools.json'; b=root/'schemas/tools.json'
check('paired_catalog_bytes',a.read_bytes()==b.read_bytes(),hashlib.sha256(a.read_bytes()).hexdigest())
cat=json.loads(a.read_text(encoding='utf-8')); check('native_catalog_count',len(cat)==85,len(cat))
fmt=next(t for t in cat if t['name']=='format_document'); check('formatter_explicit_schema',fmt['inputSchema']['properties']['formatter_profile']['type']=='string')
check('formatter_write_policy',fmt.get('policy')=='write',fmt.get('policy'))
positions=[]
def walk(v):
    if isinstance(v,dict):
        if set(v.get('properties',{}))=={'line','character'}:
            for key in ('line','character'):
                positions.append(v['properties'][key])
        for item in v.values(): walk(item)
    elif isinstance(v,list):
        for item in v: walk(item)
walk(cat)
check('lsp_integer_positions_max',len(positions)>0 and all(x.get('minimum')==0 and x.get('maximum')==2147483647 for x in positions),len(positions))
completion=next(t for t in cat if t['name']=='completion'); check('completion_count_budget_unchanged',completion['inputSchema']['properties']['limit']['maximum']==200)
for name in ('scripts/package_linux.py','scripts/package_tar.py','scripts/verify_linux_installer.py','tests/real_ide_backends.py','scripts/generate_catalog.py'):
    ast.parse((root/name).read_text(encoding='utf-8'),filename=name); check('python_ast:'+name,True)
workflows=list((root/'.github/workflows').glob('*'))
check('manual_self_hosted_workflows_only',bool(workflows) and all('workflow_dispatch:' in p.read_text(encoding='utf-8') and 'self-hosted' in p.read_text(encoding='utf-8') and 'push:' not in p.read_text(encoding='utf-8') and 'pull_request:' not in p.read_text(encoding='utf-8') for p in workflows),[p.name for p in workflows])
check('rust_lockfile_unchanged_from_base',subprocess.run(['git','diff','--exit-code','9017908f8759de74d5c3deb89e7bdb8aedcf83fd','HEAD','--','Cargo.lock','Cargo.toml','rust-toolchain.toml'],capture_output=True).returncode==0)
print(json.dumps({'status':'PASS','checks':results},ensure_ascii=False))
'@
